window.S17Page={"sceneId":"r3","caseId":"s17x-r3-maintenance-trend","name":"炼化设备预测性维护","title":"炼化设备预测性维护：先解释负荷，再追踪退化","summary":"正常负荷会抬高振动；持续超出正常关系的偏差，才值得安排一次有依据的设备检查。","directory":"expansion-cases","caseVersion":"1.0.1","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
(function(g){
'use strict';
const mean=a=>a.length?a.reduce((s,v)=>s+v,0)/a.length:0;
function rng(seed){let s=seed>>>0;return()=>((s=Math.imul(1664525,s)+1013904223>>>0)/4294967296);}
function fit(rows,key){const x=mean(rows.map(r=>r.load)),y=mean(rows.map(r=>r[key])),slope=rows.reduce((s,r)=>s+(r.load-x)*(r[key]-y),0)/rows.reduce((s,r)=>s+(r.load-x)**2,0);return{intercept:y-slope*x,slope};}
const pred=(m,x)=>m.intercept+m.slope*x;
function observe(hour,load,damage,noise,random){return{hour,load,rms:1.1+2.1*load+damage*.83+(random()-.5)*noise*.35,temperature:43+24*load+damage*2.2+(random()-.5)*noise*1.3,kurtosis:3+.25*load+damage*.47+(random()-.5)*noise*.3};}
function fitNormal(rows){return{rms:fit(rows,'rms'),temperature:fit(rows,'temperature'),kurtosis:fit(rows,'kurtosis'),trainingN:rows.length};}
function score(row,m){const expected={rms:pred(m.rms,row.load),temperature:pred(m.temperature,row.load),kurtosis:pred(m.kurtosis,row.load)};return{...row,expected,score:Math.max(0,((row.rms-expected.rms)/.35+(row.kurtosis-expected.kurtosis)/.3+(row.temperature-expected.temperature)/1.3)/3)};}
// Inference receives observations, a normal-operation model and a validation threshold only.
function infer(rows,model,threshold){let streak=0;return rows.map(r=>{const z=score(r,model);streak=z.score>threshold?streak+1:0;return{...z,flag:streak>=3,baseline:r.rms>4.5||r.temperature>80};});}
function metrics(rows,truth,key){let tp=0,fp=0,fn=0,tn=0;rows.forEach((r,i)=>{const y=truth[i].degraded; if(r[key]&&y)tp++;else if(r[key])fp++;else if(y)fn++;else tn++;});return{n:rows.length,tp,fp,fn,tn,precision:tp+fp?tp/(tp+fp):null,recall:tp+fn?tp/(tp+fn):null};}
function spectrum(row){const n=128,random=rng(170300+row.hour),fault=Math.max(0,row.rms-row.expected.rms),signal=Array.from({length:n},(_,i)=>Math.sin(2*Math.PI*8*i/n)*(1+row.load)+fault*.7*Math.sin(2*Math.PI*25*i/n)+(random()-.5)*.18);return Array.from({length:49},(_,k)=>({hz:k*4,amplitude:2*Math.hypot(...[0,1].map(q=>signal.reduce((s,v,i)=>s+v*(q?Math.sin(2*Math.PI*k*i/n):Math.cos(2*Math.PI*k*i/n)),0)))/n}));}
function run(params={}){const p={load:80,severity:1,noise:1,...params},random=rng(170303),train=Array.from({length:90},(_,i)=>observe(i,.3+.65*(i%30)/29,0,1,random)),validation=Array.from({length:45},(_,i)=>observe(i,.3+.65*(i%15)/14,0,1,random)),model=fitNormal(train),scores=validation.map(r=>score(r,model).score).sort((a,b)=>a-b),threshold=Math.max(.65,scores[Math.floor(scores.length*.98)]+.15),observations=Array.from({length:96},(_,h)=>{const load=Math.max(.25,Math.min(1,p.load/100+.14*Math.sin(h/8)));return observe(h,load,Math.max(0,h-40)*.045*p.severity,p.noise,random);}),prediction=infer(observations,model,threshold),evaluationTruth=observations.map(r=>({hour:r.hour,degraded:p.severity>0&&r.hour>=43})),alarm=prediction.find(r=>r.flag),base=prediction.find(r=>r.baseline),tail=prediction.slice(-16),avgH=mean(tail.map(r=>r.hour)),avgS=mean(tail.map(r=>r.score)),slope=tail.reduce((s,r)=>s+(r.hour-avgH)*(r.score-avgS),0)/tail.reduce((s,r)=>s+(r.hour-avgH)**2,0),last=prediction.at(-1),projected=slope>.01?Math.max(0,(8-last.score)/slope):null;return{sceneId:'r3',params:p,dataNature:'固定种子教学合成：负荷%、振动速度RMS mm/s、轴承温度°C、峭度无量纲；小时趋势独立于正常训练与验证记录',model,threshold,prediction,evaluationTruth,metrics:{model:metrics(prediction,evaluationTruth,'flag'),baseline:metrics(prediction,evaluationTruth,'baseline')},firstAlarm:alarm?.hour??null,baselineAlarm:base?.hour??null,trend:{slope,projectionHours:projected,target:8},split:{trainingNormal:90,validationNormal:45,testHours:96,truthUsedByPrediction:false}};}
g.R3Core={run,fitNormal,infer,score,spectrum};
})(globalThis);

